const raw = $json.body || $json;
const str = (v) => (typeof v === 'string' ? v.trim() : (v ?? null));

// Деньги: «60 000» -> 60000, «от 15 000 до 20 000» -> 15000 и 20000,
// «30-50 тыс.» -> 30000 и 50000, «2 млн» -> 2000000, «60.000» -> 60000.
// Два числа диапазона НЕ склеиваются в одно (было: 1500020000).
const NUM_RE = /\d[\d\s.,]*\d|\d/g;
const toNumber = (token) => {
  let s = token.replace(/\s+/g, '');
  if (/^\d{1,3}([.,]\d{3})+$/.test(s)) s = s.replace(/[.,]/g, '');
  s = s.replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const parseMoney = (v) => {
  if (v === null || v === undefined || v === '') return [];
  if (typeof v === 'number') return [Math.round(v)];
  const s = String(v).replace(/\u00a0/g, ' ');
  const scale = /млн/i.test(s) ? 1e6 : (/тыс/i.test(s) ? 1e3 : 1);
  const out = [];
  NUM_RE.lastIndex = 0;
  let m;
  while ((m = NUM_RE.exec(s)) !== null) {
    const n = toNumber(m[0]);
    if (n === null) continue;
    out.push(Math.round(n < 1000 ? n * scale : n));
  }
  return out;
};

const fromMin = parseMoney(raw.budget_min);
const fromMax = parseMoney(raw.budget_max);
const fromBudget = parseMoney(raw.budget);

// Одно число -> и минимум, и максимум (как было раньше).
// Диапазон -> минимум берём нижний, максимум верхний.
const bmin = fromMin.length
  ? Math.min(...fromMin)
  : (fromBudget.length ? Math.min(...fromBudget) : null);
const bmax = fromMax.length
  ? Math.max(...fromMax)
  : (fromBudget.length ? Math.max(...fromBudget) : null);

const payload = {
  title: str(raw.title) || '',
  description: str(raw.description) || '',
  budget_min: bmin,
  budget_max: bmax,
  url: str(raw.url) || null,
  client_name: str(raw.client_name) || null,
  external_id: str(raw.external_id) || null,
  source: 'manual'
};
return [{ json: { payload } }];

const create = $('Создать заказ в ядре').first().json;
const analyze = $input.first().json;
const bodyOf = (r) => (r && r.body) || {};

if (!create || create.statusCode >= 400) {
  const b = bodyOf(create);
  return [{ json: { code: 422, body: {
    ok: false,
    stage: 'create',
    error: b.detail || b.error || 'ядро отклонило заказ',
    order: bodyOf(create)
  } } }];
}

if (!analyze || analyze.statusCode >= 400) {
  return [{ json: { code: 502, body: {
    ok: false,
    stage: 'analyze',
    order_id: bodyOf(create).id,
    error: bodyOf(analyze).detail || bodyOf(analyze).error || 'ядро не смогло разобрать заказ'
  } } }];
}

const res = bodyOf(analyze).result || {};
return [{ json: { code: 200, body: {
  ok: true,
  order_id: bodyOf(analyze).order_id,
  decision: res.recommendation,
  needs_review: res.needs_review,
  score: res.match_score,
  reason: res.reason,
  draft_reply: res.draft_reply || null,
  handled_by: 'n8n'
} } }];
